"""
Clinical Drug-Drug Interaction (DDI) Knowledgebase & Rules Matrix
Identifies severe pharmacokinetic (CYP450 metabolism) and pharmacodynamic (QTc prolongation, bleeding) contraindications.
"""
from typing import Dict, List, Optional, Tuple, Any
from dataclasses import dataclass

@dataclass
class DrugInteraction:
    drug_a: str
    drug_b: str
    severity: str # CONTRAINDICATED, MAJOR_HIGH_RISK, MODERATE, MINOR
    mechanism: str
    clinical_effect: str
    management_advice: str

