class DrugInteractionEngine:
    @staticmethod
    def evaluate_prescription(drugs_list: List[str]) -> List[DrugInteraction]:
        flagged_interactions = []
        cleaned_drugs = [d.lower().strip() for d in drugs_list]
        for rule in INTERACTION_RULES_DATABASE:
            if rule.drug_a.lower() in cleaned_drugs and rule.drug_b.lower() in cleaned_drugs:
                if not any(f.drug_a == rule.drug_a and f.drug_b == rule.drug_b for f in flagged_interactions):
                    flagged_interactions.append(rule)
        return flagged_interactions
